<header class="page-header"><div><p class="eyebrow">Company</p><h1><?= $company===null?'New company':'Edit company' ?></h1></div></header>
<?php if(isset($errors['conflict'])):?><section class="conflict-state" role="alert"><h2>This company changed</h2><p><?= $escape($errors['conflict']) ?></p><p>Current saved values are shown. Review before resubmitting.</p></section><?php elseif($errors!==[]):?><div class="validation-summary" role="alert" tabindex="-1" data-validation-summary><h2>Please correct the form</h2><ul><?php foreach($errors as $field=>$message):?><li><a href="#<?= $escape($field) ?>"><?= $escape($message) ?></a></li><?php endforeach;?></ul></div><?php endif;?>
<?php if($duplicates!==[]):?><section class="conflict-state" role="alert"><h2>Potential duplicates found</h2><ul><?php foreach($duplicates as $match):?><li><?= $escape($match) ?></li><?php endforeach;?></ul><p>Review these records. Saving with confirmation creates or updates a separate record; it does not merge anything.</p></section><?php endif;?>
<form method="post" action="<?= $escape($actionUrl) ?>"><input type="hidden" name="_csrf" value="<?= $escape($csrfToken) ?>"><?php if($company!==null):?><input type="hidden" name="version" value="<?= $escape($company['version']) ?>"><?php endif;?>
<?php foreach(['name'=>'Company name','website'=>'Website','location'=>'Location','industry'=>'Industry','employee_range'=>'Employee range','revenue_range'=>'Revenue range'] as $field=>$label):?><div class="form-field"><label for="<?= $escape($field) ?>"><?= $escape($label) ?></label><input id="<?= $escape($field) ?>" name="<?= $escape($field) ?>" value="<?= $escape($values[$field]??'') ?>"<?= $field==='name'?' required':'' ?>><?php if(isset($errors[$field])):?><span class="field-error"><?= $escape($errors[$field]) ?></span><?php endif;?></div><?php endforeach;?>
<div class="form-field"><label for="notes">Notes</label><textarea id="notes" name="notes" rows="6"><?= $escape($values['notes']??'') ?></textarea><?php if(isset($errors['notes'])):?><span class="field-error"><?= $escape($errors['notes']) ?></span><?php endif;?></div>
<?php if($duplicates!==[]):?><label class="checkbox-field"><input type="checkbox" name="confirm_duplicate" value="1" required> Save as a separate record despite these warnings.</label><?php endif;?><div class="form-actions"><button type="submit">Save company</button><a href="<?= $escape($cancelUrl) ?>">Cancel</a></div></form>
